import{AppState}from"../store/AppState";import{toHtml}from"../utils/formatString";import{isExtensionLock}from"./extensionTypes";import{getQueuedDelayDetails,getListQueueEntries,toggleQueuedDelay}from"../services/CtblApiClient.js";import{requestUnlockQueuedDelay}from"../components/UnlockDelayModal/UnlockDelayModal";import{registerLockType}from"./registry";var EXTENSION_ID="queuedDelay";function isCurrentlyQueued(e){return!!(AppState.queuedDelays&&AppState.queuedDelays.indexOf(e)>-1)}function isConfiguredQueuedDelay(e,t){return isExtensionLock(t,EXTENSION_ID)&&!!(AppState.configuredQueuedDelays&&AppState.configuredQueuedDelays.indexOf(e)>-1)}function matches(e,t){return isCurrentlyQueued(e)||isConfiguredQueuedDelay(e,t)}function isExtensionMatch(e){return isExtensionLock(e,EXTENSION_ID)}function getDisplayState(e,t){return matches(e,t)?"Queued Delay":null}function getLockText(e,t){return isExtensionMatch(t)?"Queued delay":null}function getLockedWarning(e,t){return isExtensionMatch(t)?"With a Queued Delay":null}function getQueueListEntries(e){return $.when(getQueuedDelayDetails(),getListQueueEntries(e)).then(function(t,n){var o="";return t.filter(function(t){return t.BlockName===e}).forEach(function(t){var n=Math.max(0,Math.ceil((new Date(t.UnlockAt)-new Date)/6e4)),i=n<1?"in < 1 min.":"in "+n+" min.";o+='<div class="custom-option" onmousedown="customSelect(this, event)" data-value="'+toHtml(e).replace(/"/g,"&quot;")+'" data-entry-type="block-unlock">'+toHtml(e)+" - Unlocking - "+i+"</div>"}),n.forEach(function(e){var t,n,i=Math.max(0,Math.ceil((new Date(e.UnlockAt)-new Date)/6e4)),u=i<1?"in < 1 min.":"in "+i+" min.";0===e.TargetUrl.indexOf("REMOVE|")?(t=e.TargetUrl.substring(7),n="Removing"):0===e.TargetUrl.indexOf("REMOVE_APP|")?(t=e.TargetUrl.substring(11),n="Removing App"):(t=e.TargetUrl,n="Adding Exception"),o+='<div class="custom-option" onmousedown="customSelect(this, event)" data-value="'+toHtml(e.Id)+'" data-request-id="'+toHtml(e.Id)+'" data-entry-type="list-action">'+toHtml(t)+" - "+n+" - "+u+"</div>"}),""===o?"<div style='padding: 15px; text-align: center; opacity: 0.7;'>No pending actions for this block.</div>":o})}function getEditorLockMode(e,t){return isConfiguredQueuedDelay(e,t)?EXTENSION_ID:null}function parseEditorState(e){return{queuedDelayUnblock:e.indexOf(",")>0&&"true"==e.replace(EXTENSION_ID+",","").split(",")[0]}}function bindEditorUI(e){$("#queuedDelay_unblock").prop("checked",e.queuedDelayUnblock)}function buildLockConfig(){return EXTENSION_ID+","+$("#queuedDelay_unblock").is(":checked").toString()}function onSave(e){return toggleQueuedDelay(e,!0),AppState.configuredQueuedDelays&&-1===AppState.configuredQueuedDelays.indexOf(e)&&AppState.configuredQueuedDelays.push(e),{lock:"password",password:"CTBL_QUEUED_DELAY"}}function requestUnlock(e,t){requestUnlockQueuedDelay(e,t.continueRestrictionsCallback,t.showRestrictionsButton)}export var queuedDelayLockType={id:EXTENSION_ID,matches:matches,isExtensionMatch:isExtensionMatch,getDisplayState:getDisplayState,getLockText:getLockText,getLockedWarning:getLockedWarning,getQueueListEntries:getQueueListEntries,getEditorLockMode:getEditorLockMode,parseEditorState:parseEditorState,bindEditorUI:bindEditorUI,buildLockConfig:buildLockConfig,onSave:onSave,requestUnlock:requestUnlock};registerLockType(queuedDelayLockType);